        dialogBinding.titleInput.addTextChangedListener(object : TextWatcher {
            override fun afterTextChanged(s: Editable?) {
                dialogBinding.titleLayout.error = null
            }
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}
            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {}
        })

        dialogBinding.reminderButton.setOnClickListener {
            pickDateTime(selectedReminderTime) { pickedTime ->
                selectedReminderTime = pickedTime
                updateReminderSummary(dialogBinding, selectedReminderTime)
            }
        }

        dialogBinding.clearReminderButton.setOnClickListener {
            selectedReminderTime = null
            updateReminderSummary(dialogBinding, selectedReminderTime)
        }

        val dialog = MaterialAlertDialogBuilder(this)
            .setTitle(if (existingTask == null) "Add Task" else "Update Task")
            .setView(dialogBinding.root)
            .setPositiveButton("Save", null)
            .setNegativeButton("Cancel", null)
            .create()

        dialog.setOnShowListener {
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener {
                val title = dialogBinding.titleInput.text?.toString()?.trim().orEmpty()
                val description = dialogBinding.descriptionInput.text?.toString()?.trim().orEmpty()

                if (title.isBlank()) {
                    dialogBinding.titleLayout.error = "Title is required"
