                    title = title,
                    description = description,
                    reminderTimeMillis = selectedReminderTime,
                    createdAt = existingTask?.createdAt ?: now,
                    updatedAt = now
                )

                viewModel.saveTask(task)
                dialog.dismiss()
            }
        }

