            }
            .setNegativeButton(R.string.cancel, null)
            .show()
    }

    private fun pickDateTime(initialTimeMillis: Long?, onPicked: (Long?) -> Unit) {
        val baseCalendar = Calendar.getInstance().apply {
            timeInMillis = initialTimeMillis ?: System.currentTimeMillis()
        }

        DatePickerDialog(
            this,
            { _, year, month, dayOfMonth ->
                val timeCalendar = Calendar.getInstance().apply {
                    set(Calendar.YEAR, year)
                    set(Calendar.MONTH, month)
                    set(Calendar.DAY_OF_MONTH, dayOfMonth)
                }

                TimePickerDialog(
                    this,
                    { _, hourOfDay, minute ->
                        timeCalendar.set(Calendar.HOUR_OF_DAY, hourOfDay)
                        timeCalendar.set(Calendar.MINUTE, minute)
                        timeCalendar.set(Calendar.SECOND, 0)
                        timeCalendar.set(Calendar.MILLISECOND, 0)
                        onPicked(timeCalendar.timeInMillis)
                    },
                    timeCalendar.get(Calendar.HOUR_OF_DAY),
                    timeCalendar.get(Calendar.MINUTE),
                    false
                ).show()
            },
            baseCalendar.get(Calendar.YEAR),
            baseCalendar.get(Calendar.MONTH),
            baseCalendar.get(Calendar.DAY_OF_MONTH)
        ).show()
    }

    private fun updateReminderSummary(binding: DialogTaskBinding, reminderTimeMillis: Long?) {
        binding.reminderSummary.text = if (reminderTimeMillis == null) {
            getString(R.string.reminder_none)
        } else {
            val formatter = SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.getDefault())
            getString(R.string.reminder_at, formatter.format(Date(reminderTimeMillis)))
        }
    }
